create or replace function public.is_admin() returns boolean language sql security definer set search_path=public stable as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
revoke all on function public.is_admin() from public;grant execute on function public.is_admin() to anon,authenticated;
alter table public.profiles enable row level security;alter table public.event_categories enable row level security;alter table public.members enable row level security;alter table public.events enable row level security;alter table public.event_members enable row level security;alter table public.event_images enable row level security;alter table public.event_revisions enable row level security;
create policy profiles_read_own on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy categories_public_read on public.event_categories for select using(true);create policy categories_admin_write on public.event_categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy members_public_read on public.members for select using(true);create policy members_admin_write on public.members for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy events_public_read on public.events for select using(true);create policy events_admin_write on public.events for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy event_members_public_read on public.event_members for select using(true);create policy event_members_admin_write on public.event_members for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy event_images_public_read on public.event_images for select using(true);create policy event_images_admin_write on public.event_images for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy revisions_admin_read on public.event_revisions for select to authenticated using(public.is_admin());create policy revisions_admin_insert on public.event_revisions for insert to authenticated with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('event-media','event-media',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy event_media_public_read on storage.objects for select using(bucket_id='event-media');create policy event_media_admin_insert on storage.objects for insert to authenticated with check(bucket_id='event-media' and public.is_admin() and (storage.foldername(name))[1]='events');create policy event_media_admin_update on storage.objects for update to authenticated using(bucket_id='event-media' and public.is_admin()) with check(bucket_id='event-media' and public.is_admin());create policy event_media_admin_delete on storage.objects for delete to authenticated using(bucket_id='event-media' and public.is_admin());
